import type { Place, PlaceCategory } from './types';

// [id, category, nameRu, nameEn, nameKo, lat, lng, addressEn, addressKo, description, tags, aliases?, website?]
type Row = [
  string, PlaceCategory, string, string, string, number, number,
  string, string, string, string[], string[]?, string?,
];

const mk = (cityId: string, rows: Row[]): Place[] =>
  rows.map(([id, category, nameRu, nameEn, nameKo, lat, lng, addressEn, addressKo, description, tags, aliases, website]) => {
    const place: Place = {
      id: `${cityId}-${id}`, cityId, category, nameRu, nameEn, nameKo,
      addressEn, addressKo, lat, lng, description, tags,
    };
    if (aliases && aliases.length) place.aliases = aliases;
    if (website) place.website = website;
    return place;
  });

